style.css:
@-moz-document domain("roblox.com") {
/* Fonte: fallback com Frutiger se tiver, senão Segoe UI */
  @font-face {
    font-family: 'Frutiger';
    src: local('Frutiger'), local('Frutiger Next'), local('Segoe UI'), local('Arial'), sans-serif;
  }

  body, input, textarea, button {
    font-family: 'Frutiger', "Segoe UI", Arial, sans-serif !important;
    background: #0a121f !important;
    color: #d0e8f2 !important;
    -webkit-font-smoothing: antialiased !important;
  }

  /* Bolhas Aqua - efeito flutuante no fundo */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    pointer-events: none;
    background:
      radial-gradient(circle 80px at 10% 20%, rgba(64,224,208,0.15), transparent 70%),
      radial-gradient(circle 100px at 70% 80%, rgba(64,224,208,0.1), transparent 70%),
      radial-gradient(circle 60px at 50% 50%, rgba(64,224,208,0.12), transparent 80%);
    animation: floatBubbles 20s ease-in-out infinite;
    z-index: 0;
  }

  @keyframes floatBubbles {
    0%, 100% { background-position: 10% 20%, 70% 80%, 50% 50%; }
    50% { background-position: 15% 25%, 75% 85%, 55% 45%; }
  }

  /* Navbar e header com blur e transparência */
  header, .navbar, .topbar {
    background: rgba(10, 20, 30, 0.85) !important;
    backdrop-filter: blur(12px) saturate(180%) brightness(90%);
    border-bottom: 1px solid rgba(0, 128, 128, 0.3) !important;
    box-shadow: 0 8px 24px rgba(64,224,208,0.15);
    border-radius: 0 0 20px 20px;
    z-index: 10;
  }

  /* Cards, containers e painéis */
  .card, .container, .section {
    background: rgba(10, 25, 40, 0.7) !important;
    border-radius: 15px !important;
    box-shadow: 0 8px 20px rgba(64, 224, 208, 0.3);
    border: 1px solid rgba(64, 224, 208, 0.25) !important;
    color: #c0e9f2 !important;
  }

  /* Botões estilo Aero */
  button, .btn, input[type="submit"], .rbx-btn {
    border-radius: 14px !important;
    padding: 10px 16px !important;
    font-weight: 700 !important;
    background: linear-gradient(180deg, rgba(64,224,208,0.3), rgba(0,128,128,0.1)) !important;
    border: 1.5px solid rgba(64,224,208,0.5) !important;
    color: #a0f0e5 !important;
    box-shadow: 0 4px 16px rgba(64,224,208,0.35);
    transition: background 0.3s ease, color 0.3s ease;
  }
  button:hover, .btn:hover, input[type="submit"]:hover {
    background: linear-gradient(180deg, rgba(64,224,208,0.6), rgba(0,128,128,0.3)) !important;
    color: #e0ffff !important;
  }

  /* Inputs e campos */
  input, textarea, select {
    background: rgba(15, 30, 45, 0.7) !important;
    border: 1px solid rgba(64,224,208,0.4) !important;
    border-radius: 12px !important;
    padding: 10px 14px !important;
    color: #c0e9f2 !important;
    box-shadow: inset 0 2px 6px rgba(64,224,208,0.25);
  }

  /* Links */
  a {
    color: #40e0d0 !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline !important;
    color: #a0f0e5 !important;
  }

  /* Cabeçalhos */
  h1, h2, h3, h4 {
    font-weight: 800 !important;
    letter-spacing: -0.3px !important;
    color: #70f0e8 !important;
  }

  /* Imagens e ícones suavizados */
  img, svg {
    image-rendering: auto !important;
    shape-rendering: geometricPrecision !important;
  }

  /* Para manter tudo acima das bolhas */
  #content, .content-wrapper {
    position: relative;
    z-index: 5;
  }
}
